import numpy as np

from rllab.core.types import Policy, WorldSpec
from rllab.methods.dqn import DQN, policy_from_state
from rllab.methods.types import Learner, MethodConfig, SpecMismatchError

NEEDS = {"dqn": "Discrete", "ppo": "Box"}
SPEC_FIELDS = ("obs_len", "action")


def make_learner(
    config: MethodConfig, spec: WorldSpec, team: str, rng: np.random.Generator
) -> Learner:
    """The learner `config` names for `team`; `dqn` needs `Discrete`, `ppo` needs `Box`."""
    require_dqn(config, spec)
    return DQN(config, spec, team, rng)


def load_policy(ckpt: Checkpoint, team: str, spec: WorldSpec) -> Policy:
    """The frozen policy `team` had at `ckpt`; `SpecMismatchError` if `ckpt.spec` differs."""
    differing = [f for f in SPEC_FIELDS if getattr(ckpt.spec, f) != getattr(spec, f)]
    if differing:
        raise SpecMismatchError(differing)
    require_dqn(ckpt.methods[team], spec)
    return policy_from_state(ckpt.state[team])


def require_dqn(config: MethodConfig, spec: WorldSpec) -> None:
    """`ValueError` naming the method and action format on a mismatch, or a method not built.

    M1 builds only `dqn`; `ppo` is a later milestone's (AD-03)."""
    given = type(spec.action).__name__
    if given != NEEDS[config.method]:
        raise ValueError(f"{config.method} needs a {NEEDS[config.method]} action space, not {given}")
    if config.method != "dqn":
        raise ValueError(f"{config.method} is not built yet: only dqn learners are available")

